head.script:
scwin.__isValue = function() {
    return val = WebSquare.wUnit.getObjById('wq_uuid_1_input').value;
}
scwin.setVal = function() {
    return WebSquare.wUnit.getObjById('wq_uuid_1_input').value == scwin.__isValue();
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 샘플파일을 실행 후 날짜를 입력한다.
    //1. Run the sample file and enter the date.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wq_uuid_1_img').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wq_uuid_1_calendar_cell_4_2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('.w2calendar_time_confirm').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wq_uuid_1_input').blur()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 1. 정상적으로 날짜가 입력된다.(이전에는 시분초에 대한 validation 처리 로직이 없어서 '날짜형식이 잘못되었습니다.'라는 알림메시지 발생)
    //1. The date is entered normally (Previously there was no validation processing logic for the hour and minute seconds, resulting in a 'Date format is invalid' notification)
    WebSquare.wUnit.addCommand("assert", "scwin.setVal()", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('wq_uuid_1_input').value != ''", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 28-Feb-2018
    //End unitTest
    window.val = undefined;
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
